class Solution {
public:
    bool vowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
    int maxVowels(string s, int k) {
        int cnt = 0, best = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (vowel(s[r])) cnt++;
            int l = r - k + 1;
            if (l > 0 && vowel(s[l - 1])) cnt--;
            if (l >= 0) best = max(best, cnt);
        }
        return best;
    }
};
